/**
 * Shared helper for loading committed element-inventory baselines.
 * Baselines are generated by scripts/generate-element-inventory-baselines.js and stored in
 * tests/fixtures/element-inventory-baselines/.
 */

import { readFileSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const baselineDir = resolve(__dirname, '..', 'fixtures', 'element-inventory-baselines');

/**
 * Loads a baseline JSON file by name (e.g. 'element-inventory.json').
 * Baselines are generated from real Chrome via Selenium by
 * scripts/generate-element-inventory-baselines.js and stored in
 * tests/fixtures/element-inventory-baselines/.
 * @param {string} name - Baseline file name
 * @returns {Array<{frame: number, elements: string[]}>} The baseline inventory
 */
export function loadElementInventoryBaseline(name) {
  return JSON.parse(readFileSync(resolve(baselineDir, name), 'utf-8'));
}

/**
 * Recursively normalizes bounding box values by rounding to integers.
 * This eliminates sub-pixel drift between Chrome runs (display scaling,
 * animation frames, resource contention under parallel workers) while
 * still catching meaningful layout differences (>= 1 px shift).
 */
export function normalizeBoundingBoxes(obj) {
  if (!obj || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) return obj.map(normalizeBoundingBoxes);

  const result = {};
  for (const [key, value] of Object.entries(obj)) {
    if (key === 'boundingBox' && typeof value === 'object' && value !== null) {
      result[key] = Object.fromEntries(
        Object.entries(value).map(([k, v]) => [
          k,
          typeof v === 'number' ? Math.round(v) : v,
        ]),
      );
    } else {
      result[key] = normalizeBoundingBoxes(value);
    }
  }
  return result;
}

